// F17 Copy AI Prompt builder (T008; FR-019, SC-009).
//
// Prompt bodies are copied byte-exact from
// specs/017-workout-planner/contracts/copy-ai-prompt.md (S43-PO-5 approved);
// buildAiPrompt substitutes only the single {{PLAN_CONTENT}} token.
// GENERATED by scripts/gen-ai-prompt.mjs — do not hand-edit the bodies.

export const PLAN_CONTENT_TOKEN = '{{PLAN_CONTENT}}';

export const AI_PROMPT_EN: string =
  "You are formatting a workout plan. Turn the plan below into a clean, easy-to-follow document for the client.\n\nRules:\n1. Keep every exercise, set, rep, load, rest time, RIR, note and alternative exactly as written. Do not add, remove, replace or reorder anything.\n2. Do not change any number or unit.\n3. Do not suggest new exercises or alternatives.\n4. Make each exercise name and each alternative name a clickable link to its video URL listed in the plan. If an item has no URL, show its name as plain text.\n5. Keep exercise names in English exactly as written.\n6. Keep the coach's notes word for word.\n7. Write the headings and labels in English.\n8. If something is unclear, leave it as written instead of guessing.\n\nPlan:\n{{PLAN_CONTENT}}\n";

export const AI_PROMPT_AR: string =
  'أنت تقوم بتنسيق خطة تمارين. حوّل الخطة التالية إلى مستند واضح وسهل المتابعة للمتدرب.\n\nالقواعد:\n1. احتفظ بكل تمرين ومجموعة وعدد تكرارات ووزن ووقت راحة وRIR وملاحظة وبديل كما هو مكتوب تمامًا. لا تُضِف أي شيء ولا تحذفه ولا تستبدله ولا تغيّر ترتيبه.\n2. لا تغيّر أي رقم أو وحدة.\n3. لا تقترح تمارين أو بدائل جديدة.\n4. اجعل اسم كل تمرين واسم كل بديل رابطًا قابلًا للنقر يفتح رابط الفيديو الخاص به المذكور في الخطة. إذا لم يكن للعنصر رابط، فاعرض اسمه كنص عادي.\n5. أبقِ أسماء التمارين باللغة الإنجليزية كما هي مكتوبة.\n6. انقل ملاحظات الكابتن حرفيًا.\n7. اكتب العناوين والتسميات باللغة العربية.\n8. إذا كان هناك شيء غير واضح، فاتركه كما هو مكتوب ولا تخمّن.\n\nالخطة:\n{{PLAN_CONTENT}}\n';

export type AiPromptLocale = 'en' | 'ar';

export function buildAiPrompt(
  locale: AiPromptLocale,
  planContent: string,
): string {
  const template = locale === 'en' ? AI_PROMPT_EN : AI_PROMPT_AR;
  return template.split(PLAN_CONTENT_TOKEN).join(planContent);
}

// Prohibited instruction classes per contract section 4 (A4-5, SC-009):
//   1. invent / replace / rename / add exercises (add also covers sets)
//   2. alter / change reps, load, rest, RIR, set counts, order or any
//      programming value
//   3. generate / suggest alternatives or exercises
// Only object-qualified frames count: bare coaching verbs without their
// prohibited object (e.g. "add 5kg", "suggest heavier weight") are plan
// content, not instructions to the AI. The approved prompt bodies only ever
// use these frames inside negated prohibitions ("Do not ..."), so a negation
// cue in the same clause disqualifies the match. A sentence terminator
// (`.!?` or newline) between the cue and the verb breaks the negation.
// Plan payload after the `Plan:`/`الخطة:` marker is authorized
// content (§2) and is never scanned.
const PLAN_MARKERS = ['\nPlan:\n', '\nالخطة:\n'];

function instructionScope(prompt: string): string {
  let end = prompt.length;
  for (const marker of PLAN_MARKERS) {
    const at = prompt.indexOf(marker);
    if (at >= 0 && at < end) end = at;
  }
  return prompt.slice(0, end);
}

const NEGATION_CUE =
  /\b(do not|don't|never|must not|should not|cannot|can't|won't|no|not)\b|لا/gi;

const CLAUSE_BREAK = /[.!?\n\r]/;

function isNegated(text: string, index: number): boolean {
  const start = Math.max(0, index - 120);
  const prefix = text.slice(start, index);
  let lastNeg = -1;
  let match: RegExpExecArray | null;
  const re = new RegExp(NEGATION_CUE.source, 'gi');
  while ((match = re.exec(prefix)) !== null) {
    lastNeg = match.index + match[0].length;
  }
  if (lastNeg < 0) return false;
  const between = prefix.slice(lastNeg);
  // A sentence terminator between the cue and the verb breaks the negation.
  if (CLAUSE_BREAK.test(between)) return false;
  return true;
}

const PROHIBITED_FRAMES: RegExp[] = [
  /\b(invent|replace|rename|add)\b[\s\S]{0,60}?\bexercises?\b/gi,
  /\badd\b[\s\S]{0,40}?\bsets?\b/gi,
  /\badd\b[\s\S]{0,40}?\bset counts?\b/gi,
  /\b(alter|change)\b[\s\S]{0,80}?\b(reps?|load|rest|rir|set counts?|set count|order|programming values?|numbers?|units?)\b/gi,
  /\b(generate|suggest)\b[\s\S]{0,60}?\b(alternatives?|exercises?)\b/gi,
];

export function containsProhibitedInstruction(prompt: string): boolean {
  const scope = instructionScope(prompt);
  for (const pattern of PROHIBITED_FRAMES) {
    pattern.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = pattern.exec(scope)) !== null) {
      if (!isNegated(scope, m.index)) return true;
    }
  }
  return false;
}
